```json
{
  "root_causes": [
    {
      "service": "ts-train-food-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, COUNT(*) n, approx_quantile(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name='ts-train-food-service' AND span_name='TrainFoodController.getTrainFoodOfTrip' GROUP BY 1",
          "claim": "In the incident period, TrainFoodController.getTrainFoodOfTrip p95 is about 1434 ms across 44 spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, COUNT(*) n, approx_quantile(duration,0.95)/1e6 AS p95_ms FROM normal_traces WHERE service_name='ts-train-food-service' AND span_name='TrainFoodController.getTrainFoodOfTrip' GROUP BY 1",
          "claim": "Before the incident the same method's p95 was about 4.4 ms across 109 spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, approx_quantile(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name='ts-train-food-service' AND span_name IN ('SELECT ts.train_food','SELECT ts.train_food_list','TrainFoodRepository.findByTripId','SELECT trainFood.entity.TrainFood') GROUP BY 1",
          "claim": "Database and repository child spans stay at roughly 0.3 to 2.3 ms p95 during the incident, so the delay is not in the DB."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-food-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, approx_quantile(duration,0.95)/1e6 AS p95_ms, COUNT(*) n FROM abnormal_traces WHERE service_name='ts-food-service' AND span_name IN ('GET','FoodController.getAllFood') GROUP BY 1,2,3",
          "claim": "ts-food-service's outgoing GET to train-food waits about 1436 ms p95, while its own method time stays near 6.8 ms."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, COUNT(*) n, approx_quantile(duration,0.95)/1e6 AS p95_ms, SUM(CASE WHEN attr_status_code='ERROR' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%foodservice/foods%' GROUP BY 1",
          "claim": "User-facing GET /api/v1/foodservice/foods p95 rose to about 1459 ms (was about 32 ms), with no errors."
        }
      ]
    }
  ]
}
